// HMAC-SHA256 verification Code node
// Verifies x-signature header against HMAC_SECRET env var
// Returns early (401) if mismatch

const crypto = require('crypto');
const signature = $input.item.json.headers?.['x-signature'] || $input.item.json.headers?.['x-hub-signature-256'] || '';
const hmacSecret = process.env.HMAC_SECRET;
const body = JSON.stringify($input.item.json.body || $input.item.json);

if (!hmacSecret) {
  // No secret configured - skip verification in dev mode
  return { json: { ...$input.item.json, hmac_verified: true, skip_verify: true } };
}

const expectedSignature = 'sha256=' + crypto.createHmac('sha256', hmacSecret).update(body).digest('hex');
const isValid = crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expectedSignature));

if (!isValid && signature) {
  // Invalid signature - return error response
  throw new Error('HMAC verification failed');
}

return { json: { ...$input.item.json, hmac_verified: true } };

// Parse message from either Telegram or Baileys format
// Normalize to standard format for MiniMax LLM parsing

const body = $input.item.json.body || $input.item.json;

// Detect channel
let message = '';
let userId = '';
let channel = 'unknown';

// Telegram format
if (body.message?.text) {
  message = body.message.text;
  userId = body.message?.chat?.id?.toString() || '';
  channel = 'telegram';
}
// Baileys format (WhatsApp)
else if (body.messages && body.messages[0]) {
  const msg = body.messages[0];
  message = msg.message?.conversation || msg.message?.extendedTextMessage?.text || '';
  userId = msg.key?.remoteJid || '';
  channel = 'baileys';
}
// WhatsApp Cloud API format
else if (body.entry && body.entry[0]?.changes) {
  const changes = body.entry[0].changes[0];
  const msg = changes.value?.messages?.[0];
  message = msg?.text?.body || '';
  userId = msg?.from || '';
  channel = 'whatsapp';
}

// Extract intent keyword patterns for routing
const messageLower = message.toLowerCase().trim();

const orderKeywords = ['order', 'buy', 'purchase', 'get proxy', 'want proxy'];
const trialKeywords = ['free trial', 'trial', 'free plan', 'try free'];
const statusKeywords = ['status', 'check', 'track', 'where'];
const helpKeywords = ['help', 'menu', 'start', 'hello', 'hi'];

const intent = 
  orderKeywords.some(k => messageLower.includes(k)) ? 'order' :
  trialKeywords.some(k => messageLower.includes(k)) ? 'free_trial' :
  statusKeywords.some(k => messageLower.includes(k)) ? 'status' :
  helpKeywords.some(k => messageLower.includes(k)) ? 'help' :
  'unknown';

return {
  json: {
    channel,
    user_id: userId,
    message,
    message_raw: body,
    intent,
    reply_node_type: process.env.REPLY_NODE_TYPE || 'telegram'
  }
};

// Idempotency check using Redis
// Key prefix is configurable via IDEMPOTENCY_PREFIX env var
// Default uses staging: prefix for staging environment

const crypto = require('crypto');
const body = $input.item.json.body || $input.item.json;

// Generate idempotency key from message data
const messageId = body.update_id || body.messages?.[0]?.key?.id || body.entry?.[0]?.changes?.[0]?.value?.messages?.[0]?.id || crypto.randomBytes(8).toString('hex');
const prefix = process.env.IDEMPOTENCY_PREFIX || 'staging:';
const idempotencyKey = `${prefix}idempotency:${messageId}`;

// Store the key in Redis (we'll set via Redis node in actual execution)
// This Code node prepares the key for the Redis Set node

return {
  json: {
    ...$input.item.json,
    idempotency_key: idempotencyKey,
    already_processed: false
  }
};

// Parse LLM response and extract intent
// Handle both JSON string and object responses

let content = $input.item.json.choices?.[0]?.message?.content || '';
let parsed = {};

try {
  // Try to parse as JSON
  if (typeof content === 'string') {
    // Handle potential markdown code blocks
    content = content.replace(/^```json\n?/, '').replace(/\n?```$/, '');
    parsed = JSON.parse(content);
  } else {
    parsed = content;
  }
} catch (e) {
  // Fallback: keyword-based intent detection
  const msg = ($input.item.json.message || '').toLowerCase();
  parsed = {
    intent: msg.includes('order') ? 'order' : 
            msg.includes('trial') ? 'free_trial' : 
            msg.includes('status') ? 'status' : 
            msg.includes('help') ? 'help' : 'unknown',
    entities: {},
    original_message: msg
  };
}

return {
  json: {
    ...$input.item.json,
    intent: parsed.intent || 'unknown',
    entities: parsed.entities || {},
    llm_raw: content
  }
};

// Route reply based on REPLY_NODE_TYPE env var
// Switches between telegram and baileys (WhatsApp) reply nodes

const replyType = process.env.REPLY_NODE_TYPE || 'telegram';
const channel = $input.item.json.channel;

// Determine reply configuration
const replyConfig = {
  node_type: replyType,
  // For Telegram: use Telegram node
  // For Baileys: use HTTP webhook to Baileys runtime
  use_telegram: replyType === 'telegram' || channel === 'telegram',
  use_baileys: replyType === 'baileys' || channel === 'baileys' || channel === 'whatsapp'
};

return {
  json: {
    ...$input.item.json,
    reply_config: replyConfig,
    will_use_telegram: replyConfig.use_telegram,
    will_use_baileys: replyConfig.use_baileys
  }
};

// Generate help menu message
const message = `🇳🇬 **Styxproxy Proxy**

I can help you with:

🛒 **Order** — ISP, Residential, Mobile, Datacenter
💳 **Check Status** — Track your order
💰 **Pricing** — See all plans
❓ **Help** — How to get started
🔗 **Free Trial** — Get a free proxy

What would you like to do?`;

return { json: { ...$input.item.json, reply_message: message } };

// Generate fallback message for unknown intent
const message = `🤖 I'm not sure I understood that. Could you rephrase?

You can say things like:
- "Order ISP UK"
- "Check my order status"
- "Help"
- "How do I use proxies?"`;

return { json: { ...$input.item.json, reply_message: message } };
